'use strict';
const projects={
 flowerbed:{title:'Fresh mulch. A fresh welcome.',description:'A fresh layer of red mulch finishes the flower bed around the entrance marker.',before:'Flower bed around an address marker before mulching',after:'The same flower bed finished with fresh red mulch'},
 porch:{title:'A tidier welcome home.',description:'The planting bed beside the porch refreshed with red mulch.',before:'Bare planting bed beside a front porch before mulching',after:'The same porch planting bed covered with fresh red mulch'},
 stonebed:{title:'Let the planting shine.',description:'Overgrowth cleared from the stone-edged planting bed, revealing the hostas and natural stone border.',before:'Overgrown plants and weeds along a stone-edged foundation bed',after:'The same stone-edged bed after clearing around the hostas'},
 leaves:{title:'A fresh start for fall.',description:'Fallen leaves cleared from the lawn and front of the property.',before:'Front lawn covered in autumn leaves before cleanup',after:'The same front lawn after leaf removal'},
 hedges:{title:'A little breathing room.',description:'Overgrowth cleared and shrubs tidied around the front of the home.',before:'Overgrown shrubs and front planting beds before cleanup',after:'The same home with trimmed shrubs and cleared front beds'},
 courtyard:{title:'The courtyard, rediscovered.',description:'Weeds and overgrowth cleared around the stone courtyard.',before:'Weeds growing across a stone courtyard before cleanup',after:'The same stone courtyard after weeds and overgrowth were cleared'}
};
const tabs=[...document.querySelectorAll('[data-project]')];
function selectProject(tab){const key=tab.dataset.project,p=projects[key];tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});document.querySelector('#project-panel').setAttribute('aria-labelledby',tab.id);for(const phase of ['before','after']){const image=document.querySelector('#'+phase+'-photo');image.src='assets/'+key+'-'+phase+'.webp';image.alt=p[phase]}document.querySelector('#project-title').textContent=p.title;document.querySelector('#project-description').textContent=p.description;}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectProject(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();tabs[next].focus();selectProject(tabs[next])})});
const form=document.querySelector('#quote-form'),steps=[...form.querySelectorAll('.form-step')],error=document.querySelector('#form-error');let currentStep=0;
const recipients=['+17743652080','+15085098320'];
function isApple(){return /iPad|iPhone|iPod|Macintosh/.test(navigator.userAgent)}
function smsLink(numbers,body){return 'sms:'+numbers.join(',')+(isApple()?'&':'?')+'body='+encodeURIComponent(body)}
function showError(text,field){error.textContent=text;error.hidden=false;if(field)field.focus();else error.focus();}
function validateStep(){error.hidden=true;const controls=[...steps[currentStep].querySelectorAll('input:not([type=checkbox]),select,textarea')];if(currentStep===0&&!form.querySelector('[name=services]:checked')){showError('Choose at least one service so we know how to help.',form.querySelector('[name=services]'));return false}for(const field of controls){if(field.required&& !field.value.trim()){showError('Please complete all required fields.',field);return false}if(!field.checkValidity()){showError(field.validationMessage,field);return false}}if(currentStep===1){const digits=form.elements.phone.value.replace(/\D/g,'');if(!/^(?:1)?\d{10}$/.test(digits)){showError('Enter a valid 10-digit US phone number.',form.elements.phone);return false}if(form.elements.reply.value==='Email'&&!form.elements.email.value.trim()){showError('Add your email address so we can reply by email.',form.elements.email);return false}}return true;}
function buildMessage(){const d=new FormData(form),v=k=>String(d.get(k)||'').trim();const lines=['QUOTE REQUEST — A & A Lawn & More','', 'Name: '+v('name'),'Phone: '+v('phone')];if(v('email'))lines.push('Email: '+v('email'));lines.push('Property: '+v('address')+', '+v('city')+', '+v('zip'),'Type: '+v('property'),'Yard size: '+v('size'),'Condition: '+v('condition'),'Services: '+d.getAll('services').join('; '),'Frequency: '+v('frequency'),'Start: '+v('timing'),'Reply by: '+v('reply')+' / '+v('contactTime'),'','Work requested: '+v('details'));if(v('access'))lines.push('Access notes: '+v('access'));if(v('photos'))lines.push('Photos: '+v('photos'));return lines.join('\n');}
function showStep(step,focus=true){currentStep=step;steps.forEach((s,i)=>s.hidden=i!==step);error.hidden=true;document.querySelector('#step-count').textContent='STEP '+(step+1)+' OF 3';document.querySelectorAll('.step-track i').forEach((s,i)=>s.classList.toggle('active',i<=step));if(step===2){const message=buildMessage();document.querySelector('#message-preview').value=message;document.querySelector('#send-both').href=smsLink(recipients,message);document.querySelector('#send-aaron').href=smsLink([recipients[0]],message);document.querySelector('#send-alvin').href=smsLink([recipients[1]],message);document.querySelector('#copy-status').textContent='';}if(focus){const heading=steps[step].querySelector('h3');heading.tabIndex=-1;heading.focus({preventScroll:true});document.querySelector('.form-shell').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}}
form.querySelectorAll('.next').forEach(button=>button.addEventListener('click',()=>{if(validateStep())showStep(currentStep+1)}));form.querySelectorAll('.back').forEach(button=>button.addEventListener('click',()=>showStep(currentStep-1)));form.addEventListener('submit',event=>{event.preventDefault();if(currentStep<2&&validateStep())showStep(currentStep+1)});
document.querySelectorAll('[data-service]').forEach(link=>link.addEventListener('click',()=>{const field=[...form.querySelectorAll('[name=services]')].find(f=>f.value===link.dataset.service);if(field)field.checked=true;showStep(0,false)}));
document.querySelector('#copy-message').addEventListener('click',async()=>{const preview=document.querySelector('#message-preview'),status=document.querySelector('#copy-status');try{if(!navigator.clipboard)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(preview.value);status.textContent='Copied. Paste this request into a text to Aaron and Alvin.';}catch{preview.focus();preview.select();status.textContent='Your message is selected. Use your device’s Copy option, then paste it into your text app.'}});
document.querySelector('#year').textContent=new Date().getFullYear();
const mobileQuote=document.querySelector('.mobile-quote');if('IntersectionObserver'in window){new IntersectionObserver(entries=>{mobileQuote.classList.toggle('is-hidden',entries[0].isIntersecting)},{threshold:0}).observe(document.querySelector('#quote'));}
